import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as WorkOSUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Set once the user has signed in through WorkOS AuthKit.
  workosId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Finds the local user for a WorkOS identity, linking by email on first sign-in
// (so existing team members keep their record) or creating a new one.
async function upsertFromWorkOS(identity: WorkOSUser): Promise<User> {
  const email = identity.email.toLowerCase();
  const existing =
    users.find((u) => u.workosId === identity.id) ??
    users.find((u) => !u.workosId && u.email.toLowerCase() === email);

  if (existing) {
    existing.workosId = identity.id;
    existing.email = identity.email;
    return existing;
  }

  const name = [identity.firstName, identity.lastName].filter(Boolean).join(" ");
  const user: User = {
    id: String(users.length + 1),
    email: identity.email,
    name: name || identity.email.split("@")[0],
    createdAt: new Date().toISOString().slice(0, 10),
    workosId: identity.id,
  };
  users.push(user);
  return user;
}

// The signed-in user, or undefined for signed-out visitors.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  return user ? upsertFromWorkOS(user) : undefined;
}

// The signed-in user; redirects signed-out visitors to sign-in.
export async function requireUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return upsertFromWorkOS(user);
}
EOF

